#include <stdio.h>
#include <stdlib.h>

/* Generated by the compiler. Takes no register args; its static link slot is unused. */
extern void a60_main(void);

int main(void) {
    a60_main();
    return 0;
}

/* Heap allocation for Algol arrays (zero-initialised). */
long a60_alloc(long bytes) {
    return (long)calloc(1, (size_t)bytes);
}

/* Integer exponentiation for the ^ operator. */
long a60_ipow(long base, long exp) {
    long r = 1;
    if (exp < 0) return 0;
    while (exp > 0) {
        if (exp & 1) r *= base;
        base *= base;
        exp >>= 1;
    }
    return r;
}

/* Standard Algol-style I/O procedures; `ch` is the channel number (ignored). */
void outinteger(long ch, long n)        { (void)ch; printf("%ld\n", n); }
void outstring(long ch, const char *s)  { (void)ch; fputs(s, stdout); }
